def semver_sort(versions):
    def parse_key(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            pre_key = (1,)  # no prerelease sorts after
            return (major, minor, patch, pre_key)
        else:
            ids = pre.split('.')
            parts = []
            for ident in ids:
                if ident.isdigit():
                    parts.append((0, int(ident), ''))
                else:
                    parts.append((1, 0, ident))
            pre_key = (0, tuple(parts))
            return (major, minor, patch, pre_key)
    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse_key(pair[1]), pair[0]))
    return [v for _, v in indexed]

